import { useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";

// ─── Hotspot data per segment ─────────────────────────────────────────────────
// dx/dy  = dot position      (% of map container)
// lx/ly  = label anchor      (% of map container)
// ex/ey  = SVG line endpoint near the label (% of map container)
// anchor : "right"  → label sits LEFT  of dot (text-align: right)
//          "left"   → label sits RIGHT of dot (text-align: left)
//          "center" → label sits BELOW  the dot
const MAP_DATA = {
  truck: [
    { label: "Uttar Pradesh", pct: "2.73%", dx: 55, dy: 28, lx: 4,  ly: 16, ex: 23, ey: 22, anchor: "right"  },
    { label: "Haryana",       pct: "5.01%", dx: 53, dy: 20, lx: 64, ly: 10, ex: 64, ey: 17, anchor: "left"   },
    { label: "Telangana",     pct: "2.56%", dx: 48, dy: 59, lx: 4,  ly: 52, ex: 23, ey: 57, anchor: "right"  },
    { label: "Karnataka",     pct: "3.71%", dx: 46, dy: 66, lx: 63, ly: 60, ex: 63, ey: 65, anchor: "left"   },
    { label: "Tamil Nadu",    pct: "3.80%", dx: 50, dy: 74, lx: 32, ly: 82, ex: 44, ey: 82, anchor: "center" },
  ],
  darkstore: [
    { label: "Gujarat",     pct: "4.47%", dx: 27, dy: 39, lx: 4,  ly: 28, ex: 20, ey: 36, anchor: "right"  },
    { label: "Haryana",     pct: "4.38%", dx: 53, dy: 20, lx: 64, ly: 10, ex: 64, ey: 17, anchor: "left"   },
    { label: "Maharashtra", pct: "5.38%", dx: 34, dy: 55, lx: 4,  ly: 48, ex: 22, ey: 53, anchor: "right"  },
    { label: "Karnataka",   pct: "3.22%", dx: 46, dy: 66, lx: 63, ly: 60, ex: 63, ey: 65, anchor: "left"   },
    { label: "Tamil Nadu",  pct: "1.94%", dx: 50, dy: 74, lx: 32, ly: 82, ex: 44, ey: 82, anchor: "center" },
  ],
  delivery: [
    { label: "Gujarat",        pct: "6.22%", dx: 27, dy: 39, lx: 4,  ly: 28, ex: 20, ey: 36, anchor: "right"  },
    { label: "Madhya Pradesh", pct: "2.05%", dx: 51, dy: 41, lx: 64, ly: 27, ex: 64, ey: 35, anchor: "left"   },
    { label: "Maharashtra",    pct: "7.49%", dx: 34, dy: 55, lx: 4,  ly: 48, ex: 22, ey: 53, anchor: "right"  },
    { label: "Karnataka",      pct: "3.54%", dx: 46, dy: 66, lx: 63, ly: 60, ex: 63, ey: 65, anchor: "left"   },
    { label: "Tamil Nadu",     pct: "2.51%", dx: 50, dy: 74, lx: 32, ly: 82, ex: 44, ey: 82, anchor: "center" },
  ],
};

const SEGMENTS = [
  {
    title: "Truck Drivers",
    mapKey: "truck",
    content:
      "Truck drivers face elevated risk due to long-haul travel, extended driving hours, highway exposure, and fatigue-related incidents across inter‑state routes.",
  },
  {
    title: "Dark Store Workers",
    mapKey: "darkstore",
    content:
      "Dark store workers experience localized operational risk driven by dense urban locations, late‑night activity, inventory movement, and limited on‑ground supervision.",
  },
  {
    title: "Delivery Partners",
    mapKey: "delivery",
    content:
      "Delivery partners encounter frequent risk events due to high trip volumes, time‑bound deliveries, traffic violations, and continuous exposure to congested city roads.",
  },
];

// ─── Hotspot overlay component ────────────────────────────────────────────────
function HotspotLayer({ hotspots, visible }) {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        opacity: visible ? 1 : 0,
        transition: "opacity 0.32s ease",
        pointerEvents: "none",
      }}
    >
      {/* SVG: glow dots + connector lines */}
      <svg
        width="100%"
        height="100%"
        style={{ position: "absolute", inset: 0, overflow: "visible" }}
      >
        <defs>
          <radialGradient id="dotGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%"   stopColor="#ffffff" stopOpacity="1" />
            <stop offset="28%"  stopColor="#ff7700" stopOpacity="0.92" />
            <stop offset="62%"  stopColor="#cc2200" stopOpacity="0.45" />
            <stop offset="100%" stopColor="#880000" stopOpacity="0" />
          </radialGradient>
        </defs>

        {hotspots.map((h, i) => (
          <g key={i}>
            {/* Connector line */}
            <line
              x1={`${h.dx}%`} y1={`${h.dy}%`}
              x2={`${h.ex}%`} y2={`${h.ey}%`}
              stroke="#cc0000"
              strokeWidth="1"
              strokeLinecap="round"
            />
            {/* Outer glow halo */}
            <circle cx={`${h.dx}%`} cy={`${h.dy}%`} r="16" fill="url(#dotGlow)" />
            {/* Mid ring */}
            <circle cx={`${h.dx}%`} cy={`${h.dy}%`} r="5.5" fill="#ff4400" opacity="0.85" />
            {/* Bright core */}
            <circle cx={`${h.dx}%`} cy={`${h.dy}%`} r="2.5" fill="white" />
          </g>
        ))}
      </svg>

      {/* Text labels */}
      {hotspots.map((h, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            left: `${h.lx}%`,
            top: `${h.ly}%`,
            color: "white",
            fontFamily: "'Inter','Helvetica Neue',sans-serif",
            textAlign:
              h.anchor === "right"  ? "right"  :
              h.anchor === "center" ? "center" : "left",
            transform:
              h.anchor === "right"  ? "translateX(-100%)" :
              h.anchor === "center" ? "translateX(-50%)"  : "none",
            lineHeight: 1.15,
            whiteSpace: "nowrap",
          }}
        >
          <div style={{ fontSize: "clamp(13px, 1.7vw, 22px)", fontWeight: 700 }}>
            {h.pct}
          </div>
          <div style={{ fontSize: "clamp(9px, 1.1vw, 13px)", opacity: 0.82, marginTop: 2 }}>
            {h.label}
          </div>
        </div>
      ))}
    </div>
  );
}

// ─── Main section ─────────────────────────────────────────────────────────────
export default function GeographicSection() {
  const [openIndex, setOpenIndex]         = useState(0);        // Truck Drivers open by default
  const [activeKey, setActiveKey]         = useState("truck");  // currently displayed dataset
  const [hotspotVisible, setHotspotVisible] = useState(true);   // drives the crossfade
  const [progress, setProgress]           = useState(0);
  const sectionRef = useRef(null);

  // Fade out → swap data → fade in
  const switchMap = (newKey) => {
    if (newKey === activeKey) return;
    setHotspotVisible(false);
    setTimeout(() => {
      setActiveKey(newKey);
      setHotspotVisible(true);
    }, 320);
  };

  const handleSegmentClick = (index) => {
    const isOpen = openIndex === index;
    if (isOpen) {
      setOpenIndex(null);
      // Map keeps showing the last active dataset
    } else {
      setOpenIndex(index);
      switchMap(SEGMENTS[index].mapKey);
    }
  };

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const p = clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const titleP = ease(clamp(progress / 0.2,          0, 1));
  const leftP  = ease(clamp((progress - 0.2) / 0.25, 0, 1));
  const mapP   = ease(clamp((progress - 0.2) / 0.3,  0, 1));

  return (
    <div ref={sectionRef} style={{ height: "350vh", position: "relative" }}>
      <div
        style={{
          position: "sticky",
          top: 0,
          height: "135vh",
          overflow: "hidden",
          background: "black",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          padding: "72px 56px 40px",
        }}
      >
        {/* Background ellipse */}
        <div style={{ position: "absolute", top: 0, left: -450, zIndex: 0 }}>
          <img
            src="/assets/Ellipse.png"
            alt=""
            style={{ width: 900, height: 900 }}
          />
        </div>

        {/* Title */}
        <div
          style={{
            textAlign: "center",
            marginBottom: 8,
            opacity: titleP,
            transform: `translateY(${lerp(24, 0, titleP)}px)`,
          }}
        >
          <h2
            style={{
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              fontSize: "105px",
              fontWeight: 700,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
            }}
          >
            Geographic Risk
            <br />
            Concentration
          </h2>
          <p style={{ color: "white", fontSize: 18, margin: "12px 0 0", fontFamily: "'Inter',sans-serif" }}>
            A breakdown of states with the highest risk rates across India.
          </p>
        </div>

        {/* Body grid */}
        <div className="grid grid-cols-1 lg:grid-cols-[320px_1fr] gap-12 w-full max-w-[1200px] flex-1 mt-6">

          {/* Left panel */}
          <div
            style={{
              opacity: leftP,
              transform: `translateX(${lerp(-24, 0, leftP)}px)`,
              display: "flex",
              flexDirection: "column",
              gap: 20,
              paddingTop: 8,
            }}
          >
            <p style={{ color: "white", fontSize: 16, lineHeight: 1.7, fontFamily: "'Inter',sans-serif", margin: 0, paddingLeft: 12 }}>
              Kerala records the highest risk rate in the country, with Maharashtra close behind,
              making them two of the highest risk concentration states across segments.
            </p>
            <p style={{ color: "white", fontSize: 16, lineHeight: 1.7, fontFamily: "'Inter',sans-serif", margin: 0, paddingLeft: 12 }}>
              Another contributing factor behind this surge could be stronger crime reporting
              mechanisms in southern and western states. For example, in Kerala, many challans are
              automatically generated through AI-enabled monitoring cameras at traffic junctions.
            </p>

            {/* Accordion */}
            <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 10 }}>
              {SEGMENTS.map((item, i) => {
                const isOpen = openIndex === i;
                return (
                  <div key={i}>
                    <div
                      onClick={() => handleSegmentClick(i)}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10,
                        cursor: "pointer",
                        color: "white",
                        fontSize: 17,
                        fontWeight: 600,
                        fontFamily: "'Inter',sans-serif",
                        userSelect: "none",
                        opacity: openIndex !== null && !isOpen ? 0.38 : 1,
                        transition: "opacity 0.25s ease",
                      }}
                    >
                      <span
                        style={{
                          display: "inline-block",
                          transform: isOpen ? "rotate(90deg)" : "rotate(0deg)",
                          transition: "transform 0.25s ease",
                        }}
                      >
                        ▶
                      </span>
                      {item.title}
                    </div>

                    {/* Smooth height animation */}
                    <div
                      style={{
                        display: "grid",
                        gridTemplateRows: isOpen ? "1fr" : "0fr",
                        transition: "grid-template-rows 0.3s ease",
                      }}
                    >
                      <div style={{ overflow: "hidden" }}>
                        <div
                          style={{
                            marginLeft: 22,
                            marginTop: 6,
                            marginBottom: 4,
                            color: "rgba(255,255,255,0.75)",
                            fontSize: 14,
                            lineHeight: 1.6,
                            fontFamily: "'Inter',sans-serif",
                          }}
                        >
                          {item.content}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Map + hotspot overlay */}
          <div
            style={{
              position: "relative",
              opacity: mapP,
              transform: `scale(${lerp(0.94, 1, mapP)})`,
              height: "100%",
              maxHeight: 520,
            }}
          >
            <img
              src="/assets/india.png"
              alt="India map"
              style={{
                width: "100%",
                height: "100%",
                objectFit: "contain",
                objectPosition: "center",
                display: "block",
                filter: "brightness(0.9)",
              }}
            />

            {/* Single overlay, data swaps via fade */}
            <HotspotLayer
              hotspots={MAP_DATA[activeKey]}
              visible={hotspotVisible}
            />
          </div>
        </div>
      </div>
    </div>
  );
}
